'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const LEVELS=['入门','N5','N4','N3','N2','N1'];
const V=window.VOCAB,G=window.GRAMMAR,K=window.KANJI,F=window.FOUNDATION,R=window.READINGS,B=window.BLANKS,O=window.ORDERS,W=window.WRITING;
const ALL=[...V,...G,...K,...F,...R,...B,...O,...W];
const MAP=new Map(ALL.map(x=>[x.id,x]));
const NAV=[['home','⌂','学习总览'],['courses','▤','学习路线'],['kana','あ','假名实验室'],['vocab','語','词汇与短语'],['grammar','文','语法手册'],['kanji','字','汉字研习'],['conjugation','↝','活用工坊'],['reading','▥','分级阅读'],['writing','✎','写作练习'],['practice','◇','训练中心'],['review','↻','复习与错题'],['notebook','☆','收藏与笔记'],['stats','▦','学习统计'],['settings','⚙','偏好与存档']];
const key='kotobapath.save.v1',blankState=()=>({schema:1,profile:{level:'入门',daily:20,font:18,light:false,ruby:true},learned:{},stars:{},notes:{},reviews:{},wrong:{},drafts:{},completed:{},history:[],days:{}});
let state=blankState(),storageProblem='';

let route='home',filterLevel='全部',search='',page=1,only='all',kanaKind='hira',kanaGroup='清音',quiz=null,sessionTimer=null,writingId=W[0].id,toastTimer;
function today(date=new Date()){return [date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-');}
function safeObject(x){return x&&typeof x==='object'&&!Array.isArray(x);}
function validateSave(s){
 if(!safeObject(s)||s.schema!==1)throw Error('不是支持的 KotobaPath v1 存档');
 const n=blankState();if(!safeObject(s.profile))throw Error('缺少设置');
 const p=s.profile;n.profile={level:LEVELS.includes(p.level)?p.level:'入门',daily:Math.min(200,Math.max(5,Number(p.daily)||20)),font:Math.min(24,Math.max(18,Number(p.font)||18)),light:p.light===true,ruby:p.ruby!==false};
 for(const field of ['learned','stars','completed']){if(!safeObject(s[field]))throw Error('存档缺少 '+field);for(const [id,val]of Object.entries(s[field]))if(MAP.has(id)&&val===true)n[field][id]=true;}
 for(const field of ['notes','drafts']){if(!safeObject(s[field]))throw Error('存档缺少 '+field);for(const [id,val]of Object.entries(s[field])){if(!MAP.has(id)||typeof val!=='string'||val.length>100000)throw Error('笔记或草稿数据异常');n[field][id]=val;}}
 if(!safeObject(s.reviews)||!safeObject(s.wrong)||!safeObject(s.days)||!Array.isArray(s.history))throw Error('学习数据结构异常');
 for(const [id,r]of Object.entries(s.reviews)){if(!MAP.has(id)||!safeObject(r))continue;const nums=['due','interval','ease','seen','correct'];if(nums.some(k=>!Number.isFinite(r[k]))||r.interval<0||r.interval>3650||r.due<0||r.due>Date.now()+3651*864e5||r.ease<1.3||r.ease>4||r.seen<0||r.correct<0||r.correct>r.seen)throw Error('复习日程异常');n.reviews[id]=Object.fromEntries(nums.map(k=>[k,r[k]]));}
 for(const [id,r]of Object.entries(s.wrong)){if(!MAP.has(id)||!safeObject(r))continue;if(!Number.isFinite(r.count)||r.count<0||!Number.isFinite(r.last))throw Error('错题数据异常');n.wrong[id]={count:r.count,last:r.last};}
 for(const [d,r]of Object.entries(s.days)){if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||!safeObject(r)||!Number.isFinite(r.total)||!Number.isFinite(r.correct)||r.total<0||r.correct<0||r.correct>r.total)throw Error('统计数据异常');n.days[d]={total:r.total,correct:r.correct};}
 n.history=s.history.slice(-5000).filter(r=>safeObject(r)&&MAP.has(r.id)&&Number.isFinite(r.time)&&typeof r.ok==='boolean').map(r=>({id:r.id,time:r.time,ok:r.ok,mode:typeof r.mode==='string'?r.mode.slice(0,50):'练习'}));
 return n;
}
function save(){if(storageProblem){$('#save-status').textContent='临时进度 · 请处理存档';$('#save-status').classList.add('save-error');return false;}try{localStorage.setItem(key,JSON.stringify(state));$('#save-status').textContent='✓ 已自动保存';$('#save-status').classList.remove('save-error');return true;}catch(e){$('#save-status').textContent='保存失败 · 请导出存档';$('#save-status').classList.add('save-error');toast('本机保存失败，请导出存档以免丢失进度');return false;}}
function prefs(){document.documentElement.style.setProperty('--font',state.profile.font+'px');document.body.classList.toggle('light',state.profile.light);$('#theme').textContent=state.profile.light?'◐ 切换深色':'◐ 切换亮色';}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function badge(l){return `<span class="badge">${E(l)}</span>`;}
function btn(label,action,id='',cls=''){return `<button class="${cls}" data-act="${action}" data-id="${E(id)}">${label}</button>`;}
function heading(en,title,sub,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${en}</div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`;}
function chips(levels=LEVELS){return `<div class="chips">${['全部',...levels].map(l=>btn(E(l),'filter',l,'chip '+(filterLevel===l?'active':''))).join('')}</div>`;}
function toolbar(placeholder,filters=true){return `<div class="toolbar"><input id="search" type="search" aria-label="搜索" placeholder="${placeholder}" value="${E(search)}">${filters?`<select id="only" aria-label="掌握筛选"><option value="all" ${only==='all'?'selected':''}>全部内容</option><option value="new" ${only==='new'?'selected':''}>尚未掌握</option><option value="learned" ${only==='learned'?'selected':''}>已掌握</option><option value="star" ${only==='star'?'selected':''}>已收藏</option></select>`:''}</div>`;}
function filtered(list){return list.filter(x=>(filterLevel==='全部'||x.level===filterLevel)&&(!search||JSON.stringify(x).toLowerCase().includes(search.toLowerCase()))&&(only==='all'||only==='new'&&!state.learned[x.id]||only==='learned'&&state.learned[x.id]||only==='star'&&state.stars[x.id]));}
function pager(total){const max=Math.max(1,Math.ceil(total/24));return `<div class="pagination">${btn('← 上一页','page',page-1,page===1?'disabled-ui':'')}<span>第 ${page} / ${max} 页 · ${total.toLocaleString()} 项</span>${btn('下一页 →','page',page+1,page===max?'disabled-ui':'')}</div>`;}
function actions(x){return `<div class="actions">${btn('查看','detail',x.id)}${btn(state.stars[x.id]?'★ 已收藏':'☆ 收藏','star',x.id,state.stars[x.id]?'marked':'')}${btn(state.learned[x.id]?'✓ 已掌握':'标记掌握','learn',x.id,state.learned[x.id]?'learned':'')}</div>`;}
function dueIds(){return Object.keys(state.reviews).filter(id=>state.reviews[id].due<=Date.now()&&MAP.has(id));}
function nextLesson(){const lv=state.profile.level;if(lv==='入门')return F.find(x=>!state.completed[x.id])||F[0];return G.find(x=>x.level===lv&&!state.completed[x.id])||G.find(x=>x.level===lv);}
function home(){
 const d=state.days[today()]||{total:0,correct:0},done=Object.keys(state.learned).length,next=nextLesson(),daily=state.profile.daily;
 return heading('YOUR LANGUAGE JOURNEY','今日も、一歩ずつ。','从认识第一个假名，到读懂文字背后的想法。今天也沿着自己的节奏前进。')+`<section class="hero"><div class="hero-copy"><div class="eyebrow">CONTINUE LEARNING / 继续学习</div><h1>每一个词，<br>都是一扇新的窗。</h1><p>当前路线：${E(state.profile.level)} · ${E(next.pattern||next.title)}<br>读懂讲解，做一组训练，再把记忆交给复习。</p><div class="row">${btn('继续学习 ↗','detail',next.id,'primary')}${btn('开始今日复习','go','review','subtle')}</div></div><div class="hero-art"><div class="hero-kanji">言葉</div><small>ことばの道</small></div></section><div class="stats"><div class="stat"><small>今日训练</small><strong>${d.total}<span class="unit">/ ${daily} 目标</span></strong><div class="bar"><i style="width:${Math.min(100,d.total/daily*100)}%"></i></div></div><div class="stat"><small>待复习</small><strong>${dueIds().length}<span class="unit">项记忆</span></strong></div><div class="stat"><small>已掌握</small><strong>${done.toLocaleString()}<span class="unit">项知识</span></strong></div><div class="stat"><small>累计练习</small><strong>${Object.values(state.days).reduce((a,x)=>a+x.total,0).toLocaleString()}<span class="unit">次作答</span></strong></div></div><div class="section-head"><h2>你的学习路线</h2><a href="#courses">查看全部课程 ↗</a></div><div class="level-route">${LEVELS.map((l,i)=>{const a=l==='入门'?F:G.filter(x=>x.level===l),n=a.filter(x=>state.completed[x.id]).length;return `<div class="route-cell" role="button" tabindex="0" data-act="course-level" data-id="${l}"><small>STAGE 0${i+1}</small><strong>${l==='入门'?'あ':l}</strong><small>${['从零开始','基础表达','日常沟通','独立理解','进阶阅读','复杂语境'][i]}</small><div class="bar"><i style="width:${n/a.length*100}%"></i></div><small>${n}/${a.length} 知识课</small></div>`;}).join('')}</div><div class="grid2"><section class="panel" style="margin-top:28px"><h2>今日学习清单</h2>${[['あ','假名与文字','把读音与字形连起来','kana'],['◇','专项训练','从词义、读音到句型运用','practice'],['▥','读一篇短文','在语境中理解知识','reading']].map(([i,t,s,r])=>`<div class="task"><div class="task-icon">${i}</div><div class="task-copy">${t}<small>${s}</small></div>${btn('开始 →','go',r)}</div>`).join('')}</section><section class="panel" style="margin-top:28px"><div class="row between"><h2>本周足迹</h2><span class="small muted">作答次数</span></div>${weekChart()}<div class="small muted">完成目标比追赶进度更有意义。记得复习，也记得休息。</div></section></div>`;
}
function weekChart(){let ds=[];for(let i=6;i>=0;i--){let d=new Date();d.setDate(d.getDate()-i);ds.push({d,n:state.days[today(d)]?.total||0});}const max=Math.max(state.profile.daily,...ds.map(x=>x.n));return `<div class="week">${ds.map(({d,n},i)=>`<div class="day ${i===6?'today':''}">${n}<i style="height:${Math.max(4,n/max*88)}px"></i>${['日','一','二','三','四','五','六'][d.getDay()]}</div>`).join('')}</div>`;}
function courses(){const list=filterLevel==='全部'?[...F,...G]:filterLevel==='入门'?F:G.filter(x=>x.level===filterLevel);const a=list.filter(x=>!search||JSON.stringify(x).includes(search));return heading('CURRICULUM','一步步走向深处','按入门 → N5 → N1 学习，也可自由跳级。每一知识课先阅读、做笔记，再练习；“已读完”与“已掌握”分别记录。')+chips()+toolbar('搜索课程、语法、例句',false)+`<div class="note">${filterLevel==='全部'?'路线包含文字、基础专题与分级语法；词汇、汉字、阅读和写作请从左侧并行学习。':'建议配合本级词汇、汉字与阅读。课程可自由访问，进阶依据是理解和训练，而非点击完成。'}</div><div style="margin-top:22px">${a.map((x,i)=>`<div class="lesson"><span class="number">${state.completed[x.id]?'✓':String(i+1).padStart(2,'0')}</span><div class="lesson-copy"><h3>${E(x.pattern||x.title)}</h3><p>${E(x.meaning||x.paragraphs[0].slice(0,55)+'…')} · ${x.level}</p></div>${btn('进入课文 ↗','detail',x.id)}</div>`).join('')||empty()}</div>`;}
function empty(t='没有符合条件的内容，试着调整筛选。'){return `<div class="empty">${t}</div>`;}
function library(kind){const list=kind==='vocab'?V:kind==='grammar'?G:K;const title=kind==='vocab'?'词汇与短语':kind==='grammar'?'语法手册':'汉字研习';const sub=kind==='vocab'?`${V.length.toLocaleString()} 个中文释义词条，包含读音、词性和词库例句。支持检索、收藏、掌握与笔记。`:kind==='grammar'?`${G.length} 项中文讲解，按接续、含义、例句与易错点学习。等级为学习参考。`:`${K.length} 字，含音读、训读、笔画和关联词。字义补充为源数据英文，关联词提供中文释义。`;
 const list2=filtered(list);page=Math.min(page,Math.max(1,Math.ceil(list2.length/24)));return heading('KNOWLEDGE ATLAS',title,sub)+chips(kind==='kanji'?['N5','N4','N3','N2','N1','拓展']:['N5','N4','N3','N2','N1'])+toolbar(kind==='vocab'?'搜索日文、假名、中文释义或词性…':kind==='grammar'?'搜索句型、中文含义或接续…':'搜索汉字、读音或英文释义…')+`<div class="small muted" style="margin-bottom:18px">找到 ${list2.length.toLocaleString()} 项 · 每页 24 项</div><div class="grid3">${list2.slice((page-1)*24,page*24).map(x=>`<article class="card"><div class="row between">${badge(x.level)}<span class="small muted">${E(x.pos|| (x.char?x.strokes+' 画':'GRAMMAR'))}</span></div>${kind==='vocab'?`<a href="#" data-act="detail" data-id="${E(x.id)}" class="jp">${E(x.word)}</a>${state.profile.ruby?`<div class="reading">${E(x.reading)}</div>`:''}<p>${E(x.meaning)}</p>`:kind==='grammar'?`<a href="#" data-act="detail" data-id="${x.id}" class="jp">${E(x.pattern)}</a><p>${E(x.meaning)}</p><div class="small muted">${E(x.connect)}</div>`:`<a href="#" data-act="detail" data-id="${x.id}" class="jp kanji-char">${x.char}</a><div class="reading">${E(x.on.slice(0,3).join(' / '))}</div><p>${E(x.kun.slice(0,3).join(' / ')||'—')}</p>`}${actions(x)}</article>`).join('')}</div>${list2.length?pager(list2.length):empty()}`;
}
const kanaRows=[['あいうえお','アイウエオ',['a','i','u','e','o']],['かきくけこ','カキクケコ',['ka','ki','ku','ke','ko']],['さしすせそ','サシスセソ',['sa','shi','su','se','so']],['たちつてと','タチツテト',['ta','chi','tsu','te','to']],['なにぬねの','ナニヌネノ',['na','ni','nu','ne','no']],['はひふへほ','ハヒフヘホ',['ha','hi','fu','he','ho']],['まみむめも','マミムメモ',['ma','mi','mu','me','mo']],['や ゆ よ','ヤ ユ ヨ',['ya','','yu','','yo']],['らりるれろ','ラリルレロ',['ra','ri','ru','re','ro']],['わ   を','ワ   ヲ',['wa','','','','wo']],['ん    ','ン    ',['n','','','','']],['がぎぐげご','ガギグゲゴ',['ga','gi','gu','ge','go']],['ざじずぜぞ','ザジズゼゾ',['za','ji','zu','ze','zo']],['だぢづでど','ダヂヅデド',['da','ji','zu','de','do']],['ばびぶべぼ','バビブベボ',['ba','bi','bu','be','bo']],['ぱぴぷぺぽ','パピプペポ',['pa','pi','pu','pe','po']]];
const YOUN=[['きゃ','キャ','kya'],['きゅ','キュ','kyu'],['きょ','キョ','kyo'],['しゃ','シャ','sha'],['しゅ','シュ','shu'],['しょ','ショ','sho'],['ちゃ','チャ','cha'],['ちゅ','チュ','chu'],['ちょ','チョ','cho'],['にゃ','ニャ','nya'],['にゅ','ニュ','nyu'],['にょ','ニョ','nyo'],['ひゃ','ヒャ','hya'],['ひゅ','ヒュ','hyu'],['ひょ','ヒョ','hyo'],['みゃ','ミャ','mya'],['みゅ','ミュ','myu'],['みょ','ミョ','myo'],['りゃ','リャ','rya'],['りゅ','リュ','ryu'],['りょ','リョ','ryo'],['ぎゃ','ギャ','gya'],['ぎゅ','ギュ','gyu'],['ぎょ','ギョ','gyo'],['じゃ','ジャ','ja'],['じゅ','ジュ','ju'],['じょ','ジョ','jo'],['びゃ','ビャ','bya'],['びゅ','ビュ','byu'],['びょ','ビョ','byo'],['ぴゃ','ピャ','pya'],['ぴゅ','ピュ','pyu'],['ぴょ','ピョ','pyo'],['ファ','ファ','fa'],['フィ','フィ','fi'],['フェ','フェ','fe'],['フォ','フォ','fo'],['ティ','ティ','ti'],['ディ','ディ','di'],['シェ','シェ','she'],['チェ','チェ','che'],['ジェ','ジェ','je'],['ヴァ','ヴァ','va'],['ヴィ','ヴィ','vi'],['ヴ','ヴ','vu'],['ヴェ','ヴェ','ve'],['ヴォ','ヴォ','vo']];
const KANA=kanaRows.flatMap((r,ri)=>r[2].map((rom,i)=>rom?{id:`a${ri}-${i}`,level:'入门',h:r[0][i],k:r[1][i],rom,group:ri<11?'清音':'浊音・半浊音'}:null).filter(Boolean)).concat(YOUN.map((r,i)=>({id:'ay'+i,level:'入门',h:r[0],k:r[1],rom:r[2],group:i<33?'拗音':'外来音'})));
KANA.forEach(x=>MAP.set(x.id,x));
function kana(){const ks=KANA.filter(x=>x.group===kanaGroup);return heading('KANA LAB','从假名开始','建立字形与读音的对应关系。无音频模式下先练识读和输入，实际发音与听辨需要另行补充。',btn('假名识读训练 ↗','kana-quiz','','primary'))+`<div class="chips">${['清音','浊音・半浊音','拗音','外来音'].map(g=>btn(g,'kana-group',g,'chip '+(kanaGroup===g?'active':''))).join('')}</div><div class="row" style="margin-bottom:22px">${btn('平假名','kana-kind','hira',kanaKind==='hira'?'primary':'')}${btn('片假名','kana-kind','kata',kanaKind==='kata'?'primary':'')}${btn('阅读入门说明','detail','f1','subtle')}</div><div class="panel"><div class="kana-grid">${ks.map(x=>`<div class="kana"><b>${E(kanaKind==='hira'?x.h:x.k)}</b><small>${E(kanaKind==='hira'?x.k:x.h)}</small><small>${x.rom}</small></div>`).join('')}</div></div><div class="note">罗马字采用常见识读写法；を作助词读 o，ぢ／づ与じ／ず同音但拼写不同。长音与促音请阅读“长音、促音与拨音”专题。外来音表中的片假名没有对应日常平假名拼写。</div>`;}
function modal(x){if(!x)return;let content='';if(x.conj){content=`<h1>活用知识卡</h1><p class="jp">${E(x.wordBase)} → ${E(x.form)}</p><p>类型：${E(x.verbType)}</p><div class="example jp">${E(conjugate(x.wordBase,x.verbType)[x.form])}（${E(conjugate(x.kanaBase,x.verbType)[x.form])}）</div><p class="muted">每个动词与活用形式分别安排复习。请结合活用工坊核对规则。</p>`;}else if(x.word){content=`<h1 class="jp">${E(x.word)}</h1><p class="muted">${E(x.reading)}　${E(x.accent)}　${E(x.pos)}</p><h2>${E(x.meaning)}</h2>${x.note?`<p class="note">${E(x.note)}</p>`:''}${x.examples.map(([a,b])=>`<div class="example"><p class="jp">${E(a)}</p><p class="muted">${E(b)}</p></div>`).join('')}<p class="small muted">词汇与例句：egg rolls，CC BY-NC 4.0。已移除音频、转为纯文本。分级非官方。</p>`;}else if(x.pattern){content=`<h1 class="jp">${E(x.pattern)}</h1><h2>${E(x.meaning)}</h2><div class="note"><strong>接续</strong>　${E(x.connect)}</div><div class="example"><p class="jp">${E(x.example)}</p><p class="muted">${E(x.translation)}</p></div><h3>理解与易错点</h3><p>${E(x.note)}</p><div class="row">${btn('本级语法训练','level-practice',x.level,'primary')}${btn(state.completed[x.id]?'✓ 已读完（可取消）':'标记课文已读完','complete',x.id)}</div>`;}else if(x.char){const related=V.filter(v=>v.word.includes(x.char)).slice(0,12);content=`<h1 class="kanji-char">${E(x.char)}</h1><p>${x.strokes} 画 · ${E(x.level)} · 字义补充：${E(x.meaning.join('；'))}</p><p>音读：<span class="jp">${E(x.on.join(' ／ ')||'—')}</span></p><p>训读：<span class="jp">${E(x.kun.join(' ／ ')||'—')}</span></p><div class="note">训读中的 . 分隔汉字读音与送假名；- 表示构词位置。具体读音请结合词汇学习。</div><h3 style="margin-top:25px">关联词 · 中文释义</h3>${related.map(v=>`<div class="task"><div class="task-copy"><a href="#" data-act="detail" data-id="${E(v.id)}" class="link">${E(v.word)}　<span class="muted">${E(v.reading)}</span></a><small>${E(v.meaning)}</small></div></div>`).join('')||'<p class="muted">当前词库没有关联词。</p>'}`;}else if(x.paragraphs){content=`<h1>${E(x.title)}</h1><div class="prose">${x.paragraphs.map(p=>`<p>${E(p)}</p>`).join('')}</div><div class="row">${btn(state.completed[x.id]?'✓ 已读完（可取消）':'标记课文已读完','complete',x.id)}${btn('去假名实验室','go','kana','primary')}</div>`;}else if(x.text){content=`<h1>${E(x.title)}</h1><div class="reading-text">${E(x.text)}</div><details><summary>中文对照</summary><p>${E(x.translation)}</p></details>${btn('开始本篇阅读训练 ↗','reading-quiz',x.id,'primary')}`;}else if(x.prompt){writingId=x.id;location.hash='writing';return;}else if(x.sentence){content=`<h1>填空错题</h1><p class="jp">${E(x.sentence.replace('___','【'+x.answer+'】'))}</p><p>${E(x.why)}</p>`;}else if(x.tokens){content=`<h1>排序错题</h1><p class="jp">${E(x.tokens.join(''))}</p><p>${E(x.zh)}</p>`;}else if(x.rom){content=`<h1>${E(x.h)} ／ ${E(x.k)}</h1><p>${x.rom}</p>`;}
 $('#modal-body').innerHTML=badge(x.level)+content+`<div class="row" style="margin-top:25px">${btn(state.stars[x.id]?'★ 已收藏':'☆ 收藏','modal-star',x.id,state.stars[x.id]?'marked':'')}${btn(state.learned[x.id]?'✓ 已掌握':'标记掌握','modal-learn',x.id,state.learned[x.id]?'learned':'')}</div><label for="item-note" style="margin-top:24px">我的笔记 · 自动保存</label><textarea id="item-note" data-id="${E(x.id)}" placeholder="记录易错点、联想或自己的例句…">${E(state.notes[x.id]||'')}</textarea>`;
 if(!$('#detail').open)$('#detail').showModal();
}
const CONJ_VERBS=[['書く','五段','かく'],['泳ぐ','五段','およぐ'],['話す','五段','はなす'],['待つ','五段','まつ'],['買う','五段','かう'],['読む','五段','よむ'],['遊ぶ','五段','あそぶ'],['死ぬ','五段','しぬ'],['帰る','五段','かえる'],['行く','五段','いく'],['食べる','一段','たべる'],['見る','一段','みる'],['起きる','一段','おきる'],['する','サ变','する'],['来る','カ变','くる']];
const FORMS=['ます形','ません形','ました形','ませんでした形','ない形','なかった形','て形','た形','可能形','受身形','使役形','使役被动形','意向形','ば形','命令形','禁止形','たい形'];
function conjugate(w,type){
 const last=w.slice(-1),stem=w.slice(0,-1);let m,neg,te,ta,pot,pass,cause,vol,ba,imp;
 if(type==='サ变'){const s=w.endsWith('する')?w.slice(0,-2):'';m=s+'し';neg=s+'しない';te=s+'して';ta=s+'した';pot=s+'できる';pass=s+'される';cause=s+'させる';vol=s+'しよう';ba=s+'すれば';imp=s+'しろ';}
 else if(type==='カ变'){const s=w.endsWith('来る')?w.slice(0,-2):w.endsWith('くる')?w.slice(0,-2):'';const c=w.endsWith('来る')?'来':'';m=s+(c||'き');neg=s+(c||'こ')+'ない';te=s+(c||'き')+'て';ta=s+(c||'き')+'た';pot=s+(c||'こ')+'られる';pass=pot;cause=s+(c||'こ')+'させる';vol=s+(c||'こ')+'よう';ba=s+(c||'く')+'れば';imp=s+(c||'こ')+'い';}
 else if(type==='一段'){m=stem;neg=stem+'ない';te=stem+'て';ta=stem+'た';pot=stem+'られる';pass=pot;cause=stem+'させる';vol=stem+'よう';ba=stem+'れば';imp=stem+'ろ';}
 else{const u='うくぐすつぬぶむる',a='わかがさたなばまら',i='いきぎしちにびみり',e='えけげせてねべめれ',o='おこごそとのぼもろ',ix=u.indexOf(last);if(ix<0)return null;m=stem+i[ix];neg=stem+a[ix]+'ない';const t=['って','いて','いで','して','って','んで','んで','んで','って'][ix];te=stem+t;if(w==='行く'||w==='いく')te=stem+'って';ta=te.replace(/て$/,'た').replace(/で$/,'だ');pot=stem+e[ix]+'る';pass=stem+a[ix]+'れる';cause=stem+a[ix]+'せる';vol=stem+o[ix]+'う';ba=stem+e[ix]+'ば';imp=stem+e[ix];}
 return {'ます形':m+'ます','ません形':m+'ません','ました形':m+'ました','ませんでした形':m+'ませんでした','ない形':neg,'なかった形':neg.slice(0,-1)+'かった','て形':te,'た形':ta,'可能形':pot,'受身形':pass,'使役形':cause,'使役被动形':cause.slice(0,-1)+'られる','意向形':vol,'ば形':ba,'命令形':imp,'禁止形':w+'な','たい形':m+'たい'};
}
const CONJ_ITEMS=CONJ_VERBS.flatMap(([word,type,reading],j)=>FORMS.map((form,i)=>({id:'c-'+j+'-'+i,level:'活用',conj:true,wordBase:word,verbType:type,kanaBase:reading,form})));
CONJ_ITEMS.forEach(x=>MAP.set(x.id,x));
let conjWord='書く',conjType='五段';
function conjugation(){return heading('CONJUGATION STUDIO','活用工坊','先确定动词类型，再观察词形变化。工具生成规范基本式；敬语、不规则惯用表达与缩约式请结合专题学习。',btn('活用输入训练 ↗','conj-quiz','','primary'))+`<div class="panel"><label>常用动词示范</label><div class="chips">${CONJ_VERBS.map(([w,t])=>btn(w,'conj-example',w,'chip '+(w===conjWord?'active':''))).join('')}</div><div class="toolbar"><input id="conj-word" aria-label="辞书形" value="${E(conjWord)}" placeholder="输入辞书形，例如：勉強する"><select id="conj-type" aria-label="动词类型">${['五段','一段','サ变','カ变','い形容词','な形容词','名词'].map(t=>`<option ${t===conjType?'selected':''}>${t}</option>`).join('')}</select>${btn('生成活用表','conj-render','','primary')}</div><p class="small muted">来る保留汉字时读音会变化：来ます（きます）、来ない（こない）、来れば（くれば）。请勿仅按词尾る猜类型。い形容词いい／かっこいい使用よい系活用。</p><div id="conj-output">${conjTable()}</div></div><div class="grid2"><div class="panel"><h3>五段音便口诀</h3><p class="jp">う・つ・る → って<br>む・ぶ・ぬ → んで<br>く → いて ／ ぐ → いで<br>す → して</p><p class="muted">行く → 行って；た形将て／で换为た／だ。</p></div><div class="panel"><h3>先看结构，再背形式</h3><p>可能和被动的一段形式相同，语义靠上下文区分。使役被动先生成使役的一段形，再变被动。</p>${btn('阅读动词活用总图','detail','f6')}${btn('阅读形容词活用','detail','f7','text-btn')}</div></div>`;}
function conjTable(){let out;if(['い形容词','な形容词','名词'].includes(conjType)){if(conjType==='い形容词'){if(!conjWord.endsWith('い'))return '<p class="note">请输入以い结尾的い形容词。</p>';let st=conjWord==='いい'?'よ':conjWord.endsWith('いい')?conjWord.slice(0,-2)+'よ':conjWord.slice(0,-1);out={'基本形':conjWord,'否定':st+'くない','过去':st+'かった','过去否定':st+'くなかった','て形':st+'くて','条件形':st+'ければ','副词形':st+'く'};}else{const st=conjWord.replace(/だ$/,'');out={'基本判断':st+'だ','礼貌体':st+'です','否定':st+'ではない','过去':st+'だった','过去否定':st+'ではなかった','连接':st+'で','条件':st+'なら','修饰名词':st+(conjType==='名词'?'の':'な')};if(conjType!=='名词')out['副词形']=st+'に';}}else{if(conjType==='一段'&&!conjWord.endsWith('る')||conjType==='サ变'&&!conjWord.endsWith('する')||conjType==='カ变'&&!/(来る|くる)$/.test(conjWord))return '<p class="note">输入词尾与所选类型不符，请检查辞书形。</p>';out=conjugate(conjWord,conjType);}return out?`<div class="scroll"><table><thead><tr><th>形式</th><th>结果</th></tr></thead><tbody>${Object.entries(out).map(([k,v])=>`<tr><td>${k}</td><td class="jp">${E(v)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="note">无法生成，请输入有效辞书形并选择正确类型。</p>';}
function reading(){return heading('READING ROOM','读进一个新的世界','原创分级短文与信息检索练习。先独立阅读作答，再查看解析和中文对照。阅读范围仍需通过长篇与真实材料持续扩展。')+chips(['N5','N4','N3','N2','N1'])+`<div class="grid3">${R.filter(x=>filterLevel==='全部'||x.level===filterLevel).map((x,i)=>`<article class="card">${badge(x.level)}<h2 class="jp">${E(x.title)}</h2><p>${E(x.text.slice(0,66))}…</p><p class="small">${x.text.length} 日文字符 · ${x.questions.length} 道理解题</p><div class="row">${btn('阅读','detail',x.id)}${btn('开始作答 →','reading-quiz',x.id,'primary')}</div>${actions(x)}</article>`).join('')}</div>`;}
function writing(){const w=W.find(x=>x.id===writingId)||W[0];return heading('WRITING DESK','让想法变成日语','分级写作、草稿自动保存与自检清单。检测只提供形式提示；自由作文不进行虚假的语义自动评分。')+`<div class="toolbar"><select id="writing-select" aria-label="写作任务">${W.map(x=>`<option value="${x.id}" ${x.id===w.id?'selected':''}>${x.level} · ${E(x.title)}</option>`).join('')}</select>${btn('导出这篇作文','export-draft',w.id)}</div><div class="panel">${badge(w.level)}<h2 class="jp">${E(w.title)}</h2><p>${E(w.prompt)}</p><div class="note">目标表达：${w.targets.map(E).join(' ／ ')}。示范是短段落结构示意，不是按目标字数完成的整篇范文。</div><label for="draft" style="margin-top:20px">你的草稿</label><textarea id="draft" style="min-height:360px" data-id="${w.id}" lang="ja" placeholder="ここに書いてください…">${E(state.drafts[w.id]||'')}</textarea><div id="draft-analysis" class="small muted">${draftAnalysis(state.drafts[w.id]||'',w)}</div><details><summary>短段落示范 · 建议写完再看</summary><p class="jp">${E(w.sample)}</p></details><details><summary>提交前自检</summary><ul class="checklist"><li>有没有回答任务？观点和例子是否对应？</li><li>时态、助词、自动词与他动词是否一致？</li><li>敬体与简体是否在同一叙述层面保持一致？</li><li>授受与敬语视点是否适合说话者和对象？</li><li>有没有过度概括、重复或缺失的逻辑连接？</li><li>目标语法是否自然，而不是为了复杂而硬塞？</li></ul></details>${btn(state.completed[w.id]?'✓ 已完成（可取消）':'标记已完成自检','complete',w.id)}</div>`;}
function draftAnalysis(s,w){const len=[...s.replace(/\s/g,'')].length,paras=s.split(/\n+/).filter(x=>x.trim()).length;return `${len} 字符（不计空白） · ${paras} 段 · 目标表达字面出现：${w.targets.map(t=>`${E(t)} ${s.includes(t)?'✓':'—'}`).join(' / ')}。字面匹配无法识别所有活用形式，也不能判定用法是否正确。`;}
const MODES=[['meaning','词义选择','日文 → 中文，结合释义识别'],['reading','假名输入','看词写读音，使用日语输入法'],['reverse','词形识别','中文 → 对应日文词汇'],['grammar','句型理解','根据中文含义识别表达'],['connect','接续辨析','选择句型的规范接续'],['blank','语法填空','在完整例句中补出指定成分'],['order','句子排序','点击词块，重建目标句'],['translation','翻译重构','看中文输入目标日文句'],['conj','活用输入','五段、一段和不规则活用'],['kanji','汉字读音','选择该字的一项常见音读'],['kana','假名识读','平假名、片假名与罗马字'],['flash','闪卡自测','先回忆，再翻面并自评'],['mixed','综合练习','词汇、语法、活用与阅读混合'],['exam','限时综合','30分钟、40题，学习诊断分']];
function practice(){if(quiz)return quizView();return heading('PRACTICE CENTER','把“知道”练成“会用”','选择等级与题型，即时解析并记录错题。自动组题来自已有词条和人工编写的题目，重复抽样不计作新增知识点。')+`<div class="panel"><div class="toolbar"><label>训练级别 <select id="practice-level">${['全部','N5','N4','N3','N2','N1'].map(l=>`<option ${l===state.profile.level?'selected':''}>${l}</option>`).join('')}</select></label><label>每组题数 <select id="practice-count">${[10,20,30,50].map(n=>`<option ${n===20?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="note">输入题要求显示的标准目标；可能存在合理的其他表达，请按“查看标准答案”核对。翻译重构训练是记忆标准句，不是自由翻译自动评分。限时综合不是官方模拟卷，也不能换算JLPT合格分。</div></div><div class="grid3">${MODES.map(([m,t,s],i)=>`<article class="card"><span class="small muted">TRAINING ${String(i+1).padStart(2,'0')}</span><h2 style="margin-top:14px">${t}</h2><p>${s}</p>${btn('开始训练 ↗','start',m,'primary')}</article>`).join('')}</div>`;}
function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;}
function pick(a){return a[Math.floor(Math.random()*a.length)];}
function norm(s){return s.normalize('NFKC').replace(/[\s。．.!！?？、，,]/g,'').trim();}
function kanaNorm(s){return norm(s).replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-96));}
function answers(s){return s.split(/[／/,、；;]/).map(x=>x.replace(/（[^）]*）|\([^)]*\)/g,'').trim()).filter(Boolean);}
function makeChoice(id,prompt,answer,distractors,why,extra={}){const options=shuffle([answer,...shuffle([...new Set(distractors.filter(x=>x&&x!==answer))]).slice(0,3)]);return {id,prompt,answer,options,why,type:'choice',...extra};}
function fromItem(x,mode){
 if(x?.conj)return conjQuestion(x);
 if(x.word){const pool=V.filter(v=>v.level===x.level&&v.id!==x.id);if(mode==='reading')return{id:x.id,type:'input',prompt:`写出「${x.word}」的假名读音`,answer:x.reading,accept:answers(x.reading),kana:true,why:x.meaning+'；词库读音：'+x.reading,extra:x.word};if(mode==='reverse')return makeChoice(x.id,x.meaning,x.word,pool.map(v=>v.word),`${x.word}（${x.reading}）：${x.meaning}`);if(mode==='flash')return{id:x.id,type:'flash',prompt:x.word,answer:`${x.reading} · ${x.meaning}`,why:x.examples[0]?.join(' — ')||x.pos};return makeChoice(x.id,x.word,x.meaning,pool.map(v=>v.meaning),`${x.word}（${x.reading}）：${x.meaning}`,{sub:x.pos});}
 if(x.pattern){const pool=G.filter(v=>v.level===x.level&&v.id!==x.id);if(mode==='connect')return makeChoice(x.id,'「'+x.pattern+'」的接续是？',x.connect,pool.map(v=>v.connect),x.note+' 例：'+x.example);return makeChoice(x.id,x.meaning,x.pattern,pool.map(v=>v.pattern),x.connect+'。'+x.note+' 例：'+x.example);}
 if(x.char){if(!x.on.length)return null;return makeChoice(x.id,'「'+x.char+'」的一项常见音读是？',x.on[0],K.filter(v=>!v.on.some(r=>x.on.includes(r))).map(v=>v.on[0]),'音读：'+x.on.join(' / ')+'；训读：'+x.kun.join(' / '));}
 if(x.sentence)return{id:x.id,type:'input',prompt:x.sentence,answer:x.answer,why:x.why+' '+x.zh};
 if(x.tokens)return{id:x.id,type:mode==='translation'?'input':'order',prompt:x.zh,answer:x.tokens.join(''),tokens:x.tokens,why:'目标句：'+x.tokens.join('')+'。本题只核对目标句，其他自然表达请人工对照。'};
 if(x.text){const q=pick(x.questions);return{id:x.id,type:'choice',prompt:q.q,answer:q.options[q.answer],options:shuffle(q.options),why:q.why,text:x.text,translation:x.translation};}
 if(x.rom){const which=pick(['h','k']);return makeChoice(x.id,'「'+x[which]+'」的罗马字是？',x.rom,KANA.map(v=>v.rom),'平假名 '+x.h+'；片假名 '+x.k+'；罗马字 '+x.rom);}
 return null;
}
function conjQuestion(item=pick(CONJ_ITEMS)){const w=item.wordBase,t=item.verbType,reading=item.kanaBase,form=item.form,a=conjugate(w,t)[form];return{id:item.id,type:'input',prompt:`${w}（${reading}）· ${t} → ${form}`,answer:a,accept:[a,conjugate(reading,t)[form]],why:`规范完整式：${a}。${t==='五段'?'注意变段与て／た形音便。':t==='一段'?'一段以去る后的词干为基础。':'不规则动词需单记。'}`,form};}
function buildQuestions(mode,level,count,ids=null){let list=[];const lv=a=>a.filter(x=>level==='全部'||x.level===level);
 if(ids){return shuffle(ids).slice(0,count).map(id=>{const x=MAP.get(id);return x?.id==='f6'?conjQuestion():x?.paragraphs?fromItem(pick(KANA),'kana'):fromItem(x,'meaning');}).filter(Boolean);}
 if(mode==='conj')return Array.from({length:count},conjQuestion);
 if(mode==='mixed'||mode==='exam'){const pools=[...lv(V).map(x=>[x,pick(['meaning','reading','reverse'])]),...lv(G).map(x=>[x,'grammar']),...lv(B).map(x=>[x,'blank']),...lv(O).map(x=>[x,'order'])];const a=shuffle(lv(V)).slice(0,Math.ceil(count*.35)).map(x=>fromItem(x,pick(['meaning','reading','reverse']))),g=shuffle(lv(G)).slice(0,Math.ceil(count*.25)).map(x=>fromItem(x,'grammar')),b=shuffle(lv(B)).slice(0,Math.ceil(count*.15)).map(x=>fromItem(x,'blank')),o=shuffle(lv(O)).slice(0,Math.ceil(count*.1)).map(x=>fromItem(x,'order')),r=shuffle(lv(R)).slice(0,2).map(x=>fromItem(x));list=[...a,...g,...b,...o,...r];while(list.length<count)list.push(conjQuestion());return shuffle(list).slice(0,count);}
 if(['meaning','reading','reverse','flash'].includes(mode))list=lv(V);else if(['grammar','connect'].includes(mode))list=lv(G);else if(mode==='blank')list=lv(B);else if(['order','translation'].includes(mode))list=lv(O);else if(mode==='kanji')list=lv(K).filter(x=>x.on.length);else if(mode==='kana')list=KANA.filter(x=>x.group===kanaGroup);
 return shuffle(list).slice(0,count).map(x=>fromItem(x,mode)).filter(Boolean);
}
function startQuiz(mode,level='全部',count=20,ids=null){clearInterval(sessionTimer);const questions=buildQuestions(mode,level,count,ids);if(!questions.length){toast('这个范围还没有适合的题，请调整级别或题型。');return;}quiz={mode,level,questions,index:0,ok:0,answers:[],answered:false,start:Date.now(),limit:mode==='exam'?30*60:0,flipped:false,selected:[],tokens:null};if($('#detail').open)$('#detail').close();if(location.hash!=='#practice'){location.hash='practice';}else render();if(quiz.limit)sessionTimer=setInterval(tick,1000);}
function tick(){if(!quiz?.limit)return;const left=Math.max(0,quiz.limit-Math.floor((Date.now()-quiz.start)/1000));const el=$('#timer');if(el)el.textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;if(!left){clearInterval(sessionTimer);quiz.finished=true;render();}}
function quizView(){const qz=quiz;if(qz.finished||qz.index>=qz.questions.length)return results();const q=qz.questions[qz.index];if(!qz.tokens&&q.type==='order')qz.tokens=shuffle(q.tokens.map((t,i)=>({t,i})));const modeTitle=MODES.find(x=>x[0]===qz.mode)?.[1]||({'reading-text':'阅读理解',due:'到期复习',wrong:'错题再练'}[qz.mode]||'复习');return `<div class="quiz-wrap">${heading('FOCUSED PRACTICE',modeTitle,`${qz.level} · 第 ${qz.index+1} / ${qz.questions.length} 题`,btn('结束这组','end-quiz','','subtle'))}<div class="row between small muted"><span>已答对 ${qz.ok} 题</span><span id="timer">${qz.limit?'30:00':'不计时 · 从容思考'}</span></div><div class="bar" style="margin:12px 0 25px"><i style="width:${qz.index/qz.questions.length*100}%"></i></div><section class="panel quiz-main">${q.text?`<div class="reading-text">${E(q.text)}</div>`:''}<div class="quiz-question ${q.type==='flash'?'flash jp':''}">${E(q.prompt)}</div>${q.sub?`<p class="small muted">${E(q.sub)}</p>`:''}${q.type==='choice'?`<div class="quiz-options">${q.options.map((o,i)=>`<button class="quiz-option ${qz.answered?(o===q.answer?'correct':qz.given===o?'wrong':''):''}" data-act="answer-choice" data-id="${i}" ${qz.answered?'disabled':''}><span class="muted">${i+1}.</span> ${E(o)}</button>`).join('')}</div>`:q.type==='flash'?qz.flipped?`<div class="flash-back">${E(q.answer)}</div><p class="small muted">${E(q.why)}</p><div class="row" style="justify-content:center">${btn('没记住 · 稍后再见','flash-grade','0')}${btn('记住了','flash-grade','1','primary')}${btn('很熟练','flash-grade','2')}</div>`:btn('想好后翻面 ↻','flip','','primary'):q.type==='order'?`<div class="tokens" aria-label="已排序词块">${qz.selected.map((idx,i)=>btn(E(q.tokens[idx]),'untoken',i,'token')).join('')||'<span class="muted small">按顺序点击下方词块</span>'}</div><div class="tokens" aria-label="可选词块">${qz.tokens.filter(x=>!qz.selected.includes(x.i)).map(x=>btn(E(x.t),'token',x.i,'token')).join('')}</div>${!qz.answered?`<div class="row" style="margin-top:22px;justify-content:center">${btn('检查顺序','submit-order','','primary')}${btn('重置词块','reset-order')}</div>`:''}`:`<div class="quiz-answer"><input id="quiz-input" autocomplete="off" lang="ja" aria-label="输入答案" placeholder="使用日语输入法输入…" ${qz.answered?'disabled':''} value="${E(qz.given||'')}">${!qz.answered?btn('检查答案','submit-input','','primary'):''}</div>`}${!qz.answered&&q.type!=='flash'?`<div style="margin-top:16px">${btn('查看标准答案（记为未掌握）','reveal','','text-btn small muted')}</div>`:''}${qz.answered?`<div class="quiz-feedback"><strong style="color:var(--${qz.lastOK?'good':'red'})">${qz.lastOK?'✓ 回答正确':'需要再看一次'}</strong>${qz.given?`<p>你的答案：${E(qz.given)}</p>`:''}<p>标准答案：<span class="jp">${E(q.answer)}</span></p><p class="muted">${E(q.why)}</p>${q.translation?`<details><summary>中文对照</summary>${E(q.translation)}</details>`:''}<div class="row">${btn(qz.index+1===qz.questions.length?'查看本组报告 →':'下一题 →','next','','primary')}${btn('查看知识卡','detail',q.id)}${btn(state.stars[q.id]?'★ 已收藏':'☆ 收藏','quiz-star',q.id)}</div></div>`:''}</section><div class="note">选择题可按 1–4；输入完成按 Enter 检查，解析后按 Enter 下一题。输入法选词时不会触发提交。${q.type==='input'?'忽略空白、常见标点和全半角差异；读音题也兼容片假名。':''}</div></div>`;}
function record(id,ok,rating=1){const now=Date.now(),r=state.reviews[id]||{due:now,interval:0,ease:2.5,seen:0,correct:0};r.seen++;if(ok){r.correct++;r.interval=r.interval===0?1:r.interval===1?3:Math.min(365,r.interval*r.ease*(rating===2?1.3:1));r.ease=Math.min(3.2,r.ease+(rating===2?.1:0));r.due=now+r.interval*864e5;delete state.wrong[id];}else{r.interval=0;r.ease=Math.max(1.3,r.ease-.2);r.due=now+10*60e3;state.wrong[id]={count:(state.wrong[id]?.count||0)+1,last:now};}state.reviews[id]=r;const d=state.days[today()]||(state.days[today()]={total:0,correct:0});d.total++;if(ok)d.correct++;state.history.push({id,ok,time:now,mode:quiz?.mode||'练习'});state.history=state.history.slice(-5000);save();}
function submit(given,reveal=false,rating=1){if(!quiz||quiz.answered)return;const q=quiz.questions[quiz.index];const correct=q.type==='flash'?rating>0:!reveal&&(q.accept||[q.answer]).some(a=>(q.kana?kanaNorm(a):norm(a))===(q.kana?kanaNorm(given):norm(given)));quiz.answered=true;quiz.given=given;quiz.lastOK=correct;if(correct)quiz.ok++;quiz.answers.push({q,given,ok:correct});record(q.id,correct,rating);render();}
function results(){clearInterval(sessionTimer);const n=quiz.answers.length,total=quiz.questions.length,elapsed=Math.floor((Date.now()-quiz.start)/1000);return `<div class="quiz-wrap">${heading('SESSION COMPLETE','每次练习，都有收获。','这是本次学习诊断，不对应官方考试分数。未作答题不计入记忆日程；限时模式下计入整组得分分母。')}<div class="stats"><div class="stat"><small>诊断正确率</small><strong>${Math.round(quiz.ok/total*100)}%</strong></div><div class="stat"><small>已作答</small><strong>${n}/${total}</strong></div><div class="stat"><small>答对</small><strong>${quiz.ok}</strong></div><div class="stat"><small>用时</small><strong>${Math.floor(elapsed/60)}<span class="unit">分 ${elapsed%60} 秒</span></strong></div></div><div class="row" style="margin-bottom:28px">${btn('重新练习本组','retry','','primary')}${btn('返回训练中心','leave-quiz')}${btn('去错题本','quiz-review')}</div>${quiz.answers.map(({q,given,ok})=>`<div class="panel"><div class="small ${ok?'learned':'gold'}">${ok?'✓ 正确':'↻ 需复习'}</div><h3>${E(q.prompt)}</h3><p>你的答案：${E(given||'（查看了答案）')}<br>标准答案：${E(q.answer)}</p><p class="muted">${E(q.why)}</p>${btn('查看知识卡','detail',q.id)}</div>`).join('')}</div>`;}
function review(){const due=dueIds(),wrong=Object.keys(state.wrong).sort((a,b)=>state.wrong[b].last-state.wrong[a].last);return heading('MEMORY GARDEN','给记忆一点时间','答错后约10分钟复习；答对后依次安排1天、3天，再按熟悉度延长。此为简化间隔复习，并非FSRS。')+`<div class="grid2"><div class="panel"><h2>到期复习 <span class="gold">${due.length}</span></h2><p class="muted">今天要重新见面的知识。每组最多50项。</p>${btn('开始到期复习 ↗','review-due','','primary')}</div><div class="panel"><h2>当前错题 <span class="gold">${wrong.length}</span></h2><p class="muted">答对会移出当前错题，历史作答仍保留。</p>${btn('重练当前错题 ↗','review-wrong','','primary')}</div></div><div class="section-head"><h2>错题知识卡</h2><span class="small muted">点击查看，再有针对性复习</span></div>${wrong.length?wrong.slice(0,100).map(id=>{const x=MAP.get(id);return `<div class="lesson"><span class="number">↻</span><div class="lesson-copy"><h3>${E(itemTitle(x))}</h3><p>${E(x?.level||'')} · 当前累计错误 ${state.wrong[id].count} 次</p></div>${btn('查看解析','detail',id)}</div>`;}).join(''):empty('目前没有错题。先完成一组训练，复习计划会自动生成。')}`;}
function itemTitle(x){return (x?.conj?x.wordBase+' → '+x.form:'')||x?.word||x?.pattern||x?.char||x?.title||x?.sentence||x?.zh||x?.h||'知识卡';}
function notebook(){let ids=[...new Set([...Object.keys(state.stars),...Object.keys(state.notes).filter(id=>state.notes[id].trim())])].filter(id=>MAP.has(id)&&(!search|| (itemTitle(MAP.get(id))+' '+(state.notes[id]||'')).includes(search)));return heading('PERSONAL COLLECTION','你的词句，随手收藏','收藏跨词汇、语法、汉字与阅读。笔记在知识卡里编辑，所有内容随存档一起迁移。')+toolbar('搜索收藏标题或我的笔记…',false)+`<div class="grid3">${ids.map(id=>{const x=MAP.get(id);return `<article class="card">${badge(x.level)}<h3 style="margin-top:14px">${E(itemTitle(x))}</h3><p style="white-space:pre-wrap">${E((state.notes[id]||'还没有笔记，打开知识卡记录自己的理解。').slice(0,200))}</p>${actions(x)}</article>`;}).join('')}</div>${ids.length?'':empty('还没有收藏和笔记。打开一张知识卡，点击 ☆ 即可收藏。')}`;}
function stats(){const n=Object.values(state.days).reduce((a,x)=>a+x.total,0),c=Object.values(state.days).reduce((a,x)=>a+x.correct,0);return heading('LEARNING INSIGHTS','看见自己的积累','统计基于本机作答记录。掌握标记是自评，不代表已经达到对应考试等级。')+`<div class="stats"><div class="stat"><small>累计作答</small><strong>${n}</strong></div><div class="stat"><small>累计正确率</small><strong>${n?Math.round(c/n*100):0}%</strong></div><div class="stat"><small>学习天数</small><strong>${Object.keys(state.days).filter(d=>state.days[d].total>0).length}</strong></div><div class="stat"><small>课文已读完</small><strong>${[...F,...G].filter(x=>state.completed[x.id]).length}</strong></div></div><div class="grid2"><div class="panel"><h2>近七天训练</h2>${weekChart()}</div><div class="panel"><h2>词汇掌握分布</h2>${LEVELS.slice(1).map(l=>{const a=V.filter(x=>x.level===l),done=a.filter(x=>state.learned[x.id]).length;return `<div class="mini-chart"><label>${l}</label><div class="bar"><i style="width:${done/a.length*100}%"></i></div><span class="small muted">${done}/${a.length}</span></div>`;}).join('')}</div></div><div class="panel"><h2>近期训练记录</h2><div class="scroll"><table><thead><tr><th>时间</th><th>知识</th><th>结果</th></tr></thead><tbody>${state.history.slice(-30).reverse().map(x=>`<tr><td class="small">${new Date(x.time).toLocaleString()}</td><td>${E(itemTitle(MAP.get(x.id)))}</td><td>${x.ok?'✓ 正确':'↻ 复习'}</td></tr>`).join('')}</tbody></table></div>${n?'':empty('完成训练后将在这里显示记录。')}</div>`;}
function settings(){return heading('MAKE IT YOURS','按自己的节奏学习','存档只保存在当前浏览器，清除站点数据会删除进度。建议定期导出JSON备份；跨设备请手动导入。')+`${storageProblem?`<div class="note notice">${E(storageProblem)} ${btn('导出原始本机存档','export-raw')}${btn('保留原始备份后启用当前进度','resolve-storage')}</div>`:''}<div class="panel"><h2>学习偏好</h2><div class="toolbar"><label>当前路线<select id="pref-level">${LEVELS.map(l=>`<option ${state.profile.level===l?'selected':''}>${l}</option>`).join('')}</select></label><label>每日作答目标<select id="pref-daily">${[10,20,30,50,100].map(x=>`<option ${state.profile.daily===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="font-control"><label>字体大小</label><input id="pref-font" type="range" min="18" max="24" value="${state.profile.font}" aria-label="字体大小"><span>${state.profile.font}px</span></div><div class="row" style="margin-top:20px">${btn(state.profile.ruby?'✓ 词汇卡显示假名':'词汇卡隐藏假名','ruby')}${btn(state.profile.light?'切换深色':'切换亮色','theme')}</div><p class="small muted" style="margin-top:20px">系统日语字体决定字形；不加载CDN或网络字体。最低正文字号18px，最高24px。</p></div><div class="panel"><h2>存档迁移</h2><p>导出包含进度、复习日程、错题、收藏、笔记与作文草稿。导入前会先校验并展示概要，确认后替换本机存档，并提供当前进度备份。</p><div class="row">${btn('↗ 导出存档JSON','export','','primary')}${btn('↙ 导入存档JSON','import')}${btn('导出学习摘要','export-summary')}</div></div><div class="panel"><h2>重置进度</h2><p class="muted">需在确认框中输入 RESET。重置前会自动提供备份下载。</p>${btn('重置学习数据','reset-prompt','','danger')}</div>`;}
function about(){return heading('ABOUT KOTOBAPATH','言葉の道','纯HTML、CSS和原生JavaScript；无账户、无音频、无外部请求、不含统计追踪。')+`<div class="panel prose"><h2>当前收录与边界</h2><div class="scroll"><table><tr><th>内容</th><th>实际数量与说明</th></tr><tr><td>分级词汇</td><td>${V.length} 个中文释义词条，含开放词库例句与词性</td></tr><tr><td>语法讲解</td><td>${G.length} 项接续、例句、翻译和易错提示</td></tr><tr><td>汉字</td><td>${K.length} 字；音训、笔画、源数据英文释义与中文关联词</td></tr><tr><td>基础专题</td><td>${F.length} 课，涵盖文字、活用、助词、敬语、阅读和写作方法</td></tr><tr><td>原创阅读</td><td>${R.length} 篇，每级6篇，每篇2题；是训练起点，长篇与多文本阅读仍需扩充</td></tr><tr><td>固定句子题</td><td>${B.length} 道填空、${O.length} 道排序／翻译重构</td></tr><tr><td>写作任务</td><td>${W.length} 个；提供短段落示意与形式自检，无法自动判断自然度</td></tr></table></div><p>本项目不是对“所有日语知识点”的穷尽收录。JLPT不发布现行完整词汇、汉字和语法清单，各级标签是学习参考。276项语法和30篇阅读不足以单独构成从零到N1的完整教材，完成进度不应被解释为已达到N1。</p><p>未加入听力与口语。完整JLPT包含听力，单凭本网站的训练不能保证通过N1。应结合更广泛的阅读、分级测验与后续听力学习检验能力。</p><h2>设计参考</h2><p>参考《げんき》公开教学框架中循序引入文字、基础结构与读写的方式，并采用从基础表达走向复杂语境的分级路线。未复制其课文、练习、插图或整套知识编排。本站中文讲解、语法例句、阅读和固定句题为另行编写。</p><p><a class="link" href="https://genki3.japantimes.co.jp/en/intro/index.html" target="_blank" rel="noopener">GENKI 官方介绍 ↗</a> · <a class="link" href="https://www.jlpt.jp/e/faq/" target="_blank" rel="noopener">JLPT 官方FAQ ↗</a></p><h2>来源与许可</h2><p>代码：GPL-3.0-or-later。原创教学内容：CC BY 4.0。词汇及其例句：egg rolls 的 JLPT10k，CC BY-NC 4.0，移除音频、标签清理、转成JSON；该数据只允许非商业使用。词条分级和释义可能有误，不能当作官方标准。</p><p>汉字数据：KANJIDIC2／EDRDG（CC BY-SA 4.0）与Jonathan Waller分级，经davidluzgouveia/kanji-data整理。未使用源数据的WaniKani字段。做了筛选、字段整理，未翻译英文释义。分发时保留对应署名及许可，不将第三方数据统一改为GPL。</p><p><a href="https://github.com/5mdld/anki-jlpt-decks" target="_blank" rel="noopener" class="link">egg rolls 词库 ↗</a> · <a href="https://github.com/davidluzgouveia/kanji-data" target="_blank" rel="noopener" class="link">kanji-data ↗</a> · <a href="licenses/NOTICE.md" target="_blank" class="link">完整来源说明 ↗</a></p></div>`;}
function render(){route=(location.hash.slice(1)||'home').split('?')[0];if(!NAV.some(x=>x[0]===route)&&route!=='about')route='home';$('#crumb').textContent=NAV.find(x=>x[0]===route)?.[2]||'关于与来源';$('#nav').innerHTML=NAV.map(([r,i,t],idx)=>`${idx===9?'<div class="divider"></div>':''}<a href="#${r}" class="${route===r?'active':''}" ${route===r?'aria-current="page"':''}><b>${i}</b>${t}</a>`).join('');const pages={home,courses,kana,vocab:()=>library('vocab'),grammar:()=>library('grammar'),kanji:()=>library('kanji'),conjugation,reading,writing,practice,review,notebook,stats,settings,about};$('#main').innerHTML=pages[route]();$$('.disabled-ui').forEach(x=>x.disabled=true);prefs();if(quiz&&route==='practice'&&quiz.limit)tick();}
function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),10000);}
function exportSave(){download('kotobapath-save-'+today()+'.json',JSON.stringify(state,null,2));toast('已生成存档下载，请保管备份文件。');}
function resetFilters(){filterLevel='全部';search='';page=1;only='all';}
function toggle(field,id){if(!MAP.has(id))return;state[field][id]?delete state[field][id]:state[field][id]=true;save();}
let pendingImport=null,pendingFilter=null;
async function importFile(file){if(!file)return;if(file.size>12*1024*1024){toast('存档超过12MB，无法导入。');return;}try{pendingImport=validateSave(JSON.parse(await file.text()));$('#modal-body').innerHTML=`<h1>导入存档预览</h1><p>路线：${E(pendingImport.profile.level)}<br>掌握：${Object.keys(pendingImport.learned).length} 项<br>收藏：${Object.keys(pendingImport.stars).length} 项<br>笔记：${Object.keys(pendingImport.notes).length} 项<br>草稿：${Object.keys(pendingImport.drafts).length} 篇</p><p class="note">确认后先下载当前进度备份，再用此存档替换。请确保浏览器允许下载备份。</p>${btn('确认替换并备份当前进度','apply-import','','primary')}`;$('#detail').showModal();}catch(e){pendingImport=null;toast('导入失败：'+e.message);}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el)return;e.preventDefault();const a=el.dataset.act,id=el.dataset.id;
 switch(a){
 case'go':if($('#detail').open)$('#detail').close();location.hash=id;break;
 case'filter':filterLevel=id;page=1;render();break;
 case'page':page=Math.max(1,Number(id));render();window.scrollTo({top:80,behavior:'smooth'});break;
 case'detail':modal(MAP.get(id));break;
 case'learn':case'star':toggle(a==='learn'?'learned':'stars',id);render();break;
 case'modal-star':case'modal-learn':toggle(a==='modal-star'?'stars':'learned',id);el.textContent=a==='modal-star'?(state.stars[id]?'★ 已收藏':'☆ 收藏'):(state.learned[id]?'✓ 已掌握':'标记掌握');break;
 case'quiz-star':toggle('stars',id);render();break;
 case'complete':toggle('completed',id);el.textContent=state.completed[id]?'✓ 已读完（可取消）':'标记课文已读完';if(!$('#detail').open)render();break;
 case'course-level':state.profile.level=id;save();if(location.hash==='#courses'){filterLevel=id;render();}else{pendingFilter=id;location.hash='courses';}break;
 case'kana-group':kanaGroup=id;render();break;
 case'kana-kind':kanaKind=id;render();break;
 case'kana-quiz':startQuiz('kana','入门',20);break;
 case'conj-example':conjWord=id;conjType=CONJ_VERBS.find(x=>x[0]===id)[1];render();break;
 case'conj-render':conjWord=$('#conj-word').value.trim();conjType=$('#conj-type').value;if(!conjWord){toast('请输入辞书形');break;}$('#conj-output').innerHTML=conjTable();break;
 case'conj-quiz':startQuiz('conj','全部',20);break;
 case'level-practice':startQuiz('grammar',id,20);break;
 case'reading-quiz':{const x=MAP.get(id);startQuiz('reading-text',x.level,1,[id]);quiz.questions=x.questions.map(q=>({id:x.id,type:'choice',prompt:q.q,answer:q.options[q.answer],options:shuffle(q.options),why:q.why,text:x.text,translation:x.translation}));render();break;}
 case'start':startQuiz(id,$('#practice-level').value,id==='exam'?40:Number($('#practice-count').value));break;
 case'answer-choice':if(quiz&&!quiz.answered)submit(quiz.questions[quiz.index].options[Number(id)]);break;
 case'submit-input':{const t=$('#quiz-input');if(!t?.value.trim()){toast('先输入答案，或选择查看标准答案。');break;}submit(t.value);break;}
 case'reveal':submit('',true);break;
 case'flip':quiz.flipped=true;render();break;
 case'flash-grade':if(quiz&&!quiz.answered){submit('',false,Number(id));nextQ();}break;
 case'token':if(!quiz.answered){quiz.selected.push(Number(id));render();}break;
 case'untoken':if(!quiz.answered){quiz.selected.splice(Number(id),1);render();}break;
 case'reset-order':quiz.selected=[];render();break;
 case'submit-order':if(quiz.selected.length!==quiz.questions[quiz.index].tokens.length){toast('请先使用全部词块。');break;}submit(quiz.selected.map(i=>quiz.questions[quiz.index].tokens[i]).join(''));break;
 case'next':nextQ();break;
 case'end-quiz':quiz.finished=true;render();break;
 case'retry':{const qs=quiz.questions.map(q=>({...q,options:q.options?shuffle(q.options):undefined})),mode=quiz.mode,level=quiz.level;clearInterval(sessionTimer);quiz={mode,level,questions:shuffle(qs),index:0,ok:0,answers:[],answered:false,start:Date.now(),limit:mode==='exam'?1800:0,flipped:false,selected:[],tokens:null};if(quiz.limit)sessionTimer=setInterval(tick,1000);render();break;}
 case'leave-quiz':clearInterval(sessionTimer);quiz=null;render();break;
 case'quiz-review':clearInterval(sessionTimer);quiz=null;location.hash='review';break;
 case'review-due':if(!dueIds().length){toast('目前没有到期复习，可先做新训练。');break;}startQuiz('due','全部',50,dueIds());break;
 case'review-wrong':if(!Object.keys(state.wrong).length){toast('目前没有错题。');break;}startQuiz('wrong','全部',50,Object.keys(state.wrong));break;
 case'ruby':state.profile.ruby=!state.profile.ruby;save();render();break;
 case'theme':state.profile.light=!state.profile.light;prefs();save();if(route==='settings')render();break;
 case'export':exportSave();break;
 case'export-raw':try{download('kotobapath-original-backup.json',localStorage.getItem(key)||'{}');}catch(e){toast('无法访问原始存档。');}break;
 case'resolve-storage':try{download('kotobapath-original-backup.json',localStorage.getItem(key)||'{}');storageProblem='';save();render();}catch(e){toast('无法读取存档，请先允许本地存储并导出当前进度。');}break;
 case'import':$('#import-file').click();break;
 case'apply-import':if(pendingImport){exportSave();const prev=state;state=pendingImport;const oldProblem=storageProblem;storageProblem='';if(save()){pendingImport=null;$('#detail').close();quiz=null;clearInterval(sessionTimer);render();toast('存档已导入');}else{state=prev;storageProblem=oldProblem;toast('保存失败，已保留原进度，未应用导入。');}}break;
 case'export-draft':{const w=MAP.get(id);download('kotobapath-'+w.level+'-'+id+'.txt',w.title+'\n\n'+(state.drafts[id]||''),'text/plain;charset=utf-8');break;}
 case'export-summary':download('kotobapath-progress-'+today()+'.txt','KotobaPath 学习摘要\n'+today()+'\n当前路线：'+state.profile.level+'\n已掌握：'+Object.keys(state.learned).length+'\n收藏：'+Object.keys(state.stars).length+'\n学习天数：'+Object.keys(state.days).length+'\n自评进度不代表JLPT能力认定。','text/plain;charset=utf-8');break;
 case'reset-prompt':$('#modal-body').innerHTML='<h1>重置学习进度</h1><p>输入 RESET 确认。当前进度会先生成备份下载。</p><input id="reset-confirm" aria-label="输入RESET" autocomplete="off">'+btn('备份并重置','reset-confirm','','danger');$('#detail').showModal();break;
 case'reset-confirm':if($('#reset-confirm').value==='RESET'){exportSave();state=blankState();storageProblem='';save();quiz=null;clearInterval(sessionTimer);$('#detail').close();render();toast('已重置进度。');}else toast('输入不匹配，未重置。');break;
 }
});
function nextQ(){if(!quiz?.answered)return;quiz.index++;quiz.answered=false;quiz.given='';quiz.flipped=false;quiz.selected=[];quiz.tokens=null;render();window.scrollTo({top:0,behavior:'smooth'});}
let searchTimeout;
document.addEventListener('input',e=>{const t=e.target;if(t.id==='search'){if(e.isComposing)return;const pos=t.selectionStart;search=t.value;page=1;clearTimeout(searchTimeout);searchTimeout=setTimeout(()=>{render();const x=$('#search');x?.focus();try{x?.setSelectionRange(pos,pos);}catch(e){}},150);}if(t.id==='item-note'){state.notes[t.dataset.id]=t.value;save();}if(t.id==='draft'){state.drafts[t.dataset.id]=t.value;save();$('#draft-analysis').innerHTML=draftAnalysis(t.value,MAP.get(t.dataset.id));}if(t.id==='pref-font'){state.profile.font=Number(t.value);prefs();t.nextElementSibling.textContent=t.value+'px';save();}});
document.addEventListener('compositionend',e=>{if(e.target.id==='search')e.target.dispatchEvent(new Event('input',{bubbles:true}));});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='only'){only=t.value;page=1;render();}if(t.id==='writing-select'){writingId=t.value;render();}if(t.id==='pref-level'){state.profile.level=t.value;save();}if(t.id==='pref-daily'){state.profile.daily=Number(t.value);save();}if(t.id==='import-file'){importFile(t.files[0]);t.value='';}});
document.addEventListener('keydown',e=>{if(e.isComposing||e.keyCode===229||$('#detail').open)return;const active=document.activeElement;if(e.key==='Enter'&&active?.dataset.act&&active.tagName!=='BUTTON'&&active.tagName!=='A'){active.click();return;}if(route!=='practice'||!quiz||quiz.finished||quiz.index>=quiz.questions.length)return;const q=quiz.questions[quiz.index];if(e.key==='Enter'){if(quiz.answered){e.preventDefault();nextQ();}else if(q.type==='input'&&active?.id==='quiz-input'){e.preventDefault();if(active.value.trim())submit(active.value);}}else if(q.type==='choice'&&!quiz.answered&&/^[1-4]$/.test(e.key)&&!['INPUT','TEXTAREA','SELECT'].includes(active?.tagName)){const a=q.options[Number(e.key)-1];if(a)submit(a);}});
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView();};
$('#theme').onclick=()=>{state.profile.light=!state.profile.light;prefs();save();};$('#export-top').onclick=exportSave;$('#close-modal').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});$('#detail').addEventListener('close',()=>{if(!quiz||route!=='practice')render();});
$('#menu').onclick=()=>document.body.classList.toggle('menu-open');
window.addEventListener('hashchange',()=>{clearTimeout(searchTimeout);resetFilters();if(pendingFilter){filterLevel=pendingFilter;pendingFilter=null;}document.body.classList.remove('menu-open');if($('#detail').open)$('#detail').close();render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===key){storageProblem='另一标签页更改了存档。为避免互相覆盖，请导出当前进度后刷新页面。';$('#save-status').textContent='其他标签页已更改存档';$('#save-status').classList.add('save-error');toast(storageProblem);}});
try{const raw=localStorage.getItem(key);if(raw)state=validateSave(JSON.parse(raw));}catch(e){storageProblem='存档未能读取，当前使用临时进度。请先到设置中导出原始备份。';}
render();if(storageProblem){$('#save-status').textContent='存档读取异常';toast(storageProblem);}
